def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v}
    comps=[]
    for c in colors:
        cells={(r,x) for r in range(h) for x in range(w) if grid[r][x]==c}
        while cells:
            stack=[cells.pop()]; comp=set(stack)
            while stack:
                r,x=stack.pop()
                for q in ((r-1,x),(r+1,x),(r,x-1),(r,x+1)):
                    if q in cells:
                        cells.remove(q); comp.add(q); stack.append(q)
            comps.append((c,comp))
    top=min(r for c,comp in comps if c==8 for r,x in comp)
    out=[[0]*w for _ in range(h)]
    for c,comp in comps:
        dy=top-min(r for r,x in comp)
        for r,x in comp:
            if r+dy<h: out[r+dy][x]=c
    return out
